head.script:
scwin.onpageload = function() {
    wcMain.createWindow("title", null, "windowContainer_setFocusedCell_WEFF-802_(WSQ-4152)_sub.xml", "winTitle", "winId", "existWindow", null, "", null, null, "wframe");
};
scwin.onpageunload = function() {};
scwin.checkVal = function() {
    var temp = WebSquare.wUnit.getDomById('G_'+$p.id+'wcMain_subWindow0_wframe_gridView1___selectbox_col1_itemTable').style.top;
    return parseInt(temp) < 1000;
    // return temp.indexOf("error문구");
    // return temp.indexOf("error");
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wcMain_subWindow0_wframe_trigger1').click()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wcMain_subWindow0_wframe_trigger6').click()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
